483	@customElement("powerpilot-panel")
484	export class PowerPilotPanel extends LitElement {
485	  @property({ attribute: false }) hass: any;
486	  @property({ attribute: false }) narrow = false;
487	
488	  @state() private _tab: Tab = "overview";
489	  @state() private _plan: Plan | null = null;
490	  @state() private _status: Status | null = null;
491	  @state() private _log: LogEvent[] = [];
492	  @state() private _profiles: Profiles | null = null;
493	  @state() private _stats: ConsumptionStats | null = null;
494	  @state() private _statsLoading = false;
495	  @state() private _statsKey: string | null = null;
496	  @state() private _forecasts: Forecasts | null = null;
497	  @state() private _series: Series | null = null;
498	  @state() private _error: string | null = null;
499	
500	  /** Debug dump state (generated on demand from the Debug tab). */
501	  @state() private _diagnostics: Diagnostics | null = null;
502	  @state() private _diagnosticsLoading = false;
503	
504	  /** "Przepływ" tab: live pipeline snapshot. */
505	  @state() private _flow: FlowData | null = null;
506	  @state() private _flowLoading = false;
507	
508	  @state() private _debug: unknown = null;
509	  @state() private _debugLoading = false;
510	  @state() private _debugError: string | null = null;
511	  @state() private _debugCopied = false;
512	
513	  /** Active range preset. */
514	  @state() private _rangeMode: RangeMode = "3d";
515	  /** Selected day. Null = today (live). When set (to a past day) it is the
516	   *  window's start; the chart shows that day's realized data plus, on the
517	   *  right, the current plan's forecast horizon. */
518	  @state() private _anchor: Date | null = null;
519	  /** Selected forecast lead (hours) for the past "prognoza" comparison. */
520	  @state() private _forecastLead = 0;
521	  /** Exact prognoza pin: show the plan in force at this local datetime
522	   *  (ISO, hour precision). Takes precedence over the lead buttons. */
523	  @state() private _forecastRunAt: string | null = null;
524	  /** Selected day on the Prices tab (ISO string YYYY-MM-DD). Null = today. */
525	  @state() private _pricesDay: string | null = null;
526	  /** Price archive payload for the selected day (independent of the chart window). */
527	  @state() private _pricesData: PriceArchive | null = null;
528	  @state() private _pricesLoading = false;
529	
530	  /** Simulations tab: available vintages, the two compared snapshots, accuracy. */
531	  @state() private _snapshotRuns: SnapshotRun[] = [];
532	  @state() private _snapA: string | null = null;
533	  @state() private _snapB: string | null = null;
534	  @state() private _snapDataA: SnapshotPayload | null = null;
535	  @state() private _snapDataB: SnapshotPayload | null = null;
536	  @state() private _accuracy: Accuracy | null = null;
537	  @state() private _accuracyLead = 24;
538	  @state() private _simLoading = false;
539	
540	  private _timer?: number;
541	  private _energyChart?: ApexCharts;
542	  private _priceChart?: ApexCharts;
543	  private _compareChart?: ApexCharts;
544	  private _accuracyChart?: ApexCharts;
545	  private _biasChart?: ApexCharts;
546	  /** Reference to the last Series payload mounted into the charts. Used to
547	   *  short-circuit Lit updates that don't actually change the data, so user
548	   *  interactions (zoom, tooltip) survive periodic refreshes. */
549	  private _lastMountedSeries?: Series;
550	
551	  connectedCallback(): void {
552	    super.connectedCallback();
553	    this._refresh();
554	    this._timer = window.setInterval(() => this._refresh(), 60000);
555	  }
556	
557	  disconnectedCallback(): void {
558	    if (this._timer) window.clearInterval(this._timer);
559	    this._energyChart?.destroy();
560	    this._priceChart?.destroy();
561	    this._energyChart = undefined;
562	    this._priceChart = undefined;
563	    this._destroySimCharts();
564	    super.disconnectedCallback();
565	  }
566	
567	  /** Local midnight (00:00) of the given date. */
568	  private _midnight(d: Date): Date {
569	    const m = new Date(d);
570	    m.setHours(0, 0, 0, 0);
571	    return m;
572	  }
573	
574	  /** Compute the start/end of the current window.
575	   *
576	   * The window starts at the selected anchor — local midnight when picked from
577	   * the date field, and possibly noon after « / » stepping (they move in 12 h
578	   * half-days) — and spans 24h / 3d / 7d from there. `_anchor` holds that
579	   * start; `null` means "today from midnight" (live). The selected moment is
580	   * therefore always the left edge of the chart. */
581	  private _computeWindow(): { start: Date; end: Date; pastHours: number } {
582	    const hours = RANGE_HOURS[this._rangeMode];
583	    const start = this._anchor ? new Date(this._anchor) : this._midnight(new Date());
584	    start.setMinutes(0, 0, 0);
585	    const end = new Date(start.getTime() + hours * 3600 * 1000);
586	    return { start, end, pastHours: hours };
587	  }
588	
589	  private async _refresh(): Promise<void> {
590	    if (!this.hass) return;
591	    try {
592	      const { start, end, pastHours } = this._computeWindow();
593	      const [plan, status, log, profiles, series] = await Promise.all([
594	        this.hass.callWS({ type: "powerpilot/plan" }),
595	        this.hass.callWS({ type: "powerpilot/status" }),
596	        this.hass.callWS({ type: "powerpilot/log" }),
597	        this.hass.callWS({ type: "powerpilot/profiles" }),
598	        this.hass.callWS({
599	          type: "powerpilot/series",
600	          past_hours: pastHours,
601	          start: start.toISOString(),
602	          end: end.toISOString(),
603	          // `forecast_lead` picks how far out the past "prognoza" comparison is
604	          // read from (0 = the freshest plan made as each hour began).
605	          forecast_lead: this._forecastLead,
606	          // Exact pin beats the lead: show the plan in force at that moment.
607	          ...(this._forecastRunAt ? { forecast_run_at: this._forecastRunAt } : {}),
608	        }),
609	      ]);
610	      this._plan = plan;
611	      this._status = status;
612	      this._log = log?.events ?? [];
613	      this._profiles = profiles;
614	      this._series = series;
615	      this._error = null;
616	      // Keep the price archive fresh while it's on screen (today's rows pick up
617	      // newly confirmed / re-forecast prices between source fetches).
618	      if (this._tab === "prices") this._loadPrices();
619	      // Pick up newly recorded vintages + fresh actuals; A/B selection is kept.
620	      if (this._tab === "simulations") this._loadSimulations();
621	      // Keep the pipeline snapshot live while it's on screen.
622	      if (this._tab === "flow") this._loadFlow();
623	    } catch (err: any) {
624	      this._error = err?.message ?? String(err);
625	    }
626	  }
627	
628	  private _setRange(mode: RangeMode): void {
629	    this._rangeMode = mode;
630	    this._refresh();
631	  }
632	
633	  /** Move the window start by ±12 h (the « / » buttons) — half-day hops make
