681	  /** The datetime the prognoza is effectively pinned to: the explicit pick, or
682	   *  the vintage the backend resolved a lead preset (−3h, −6h…) to. Null when
683	   *  nothing is pinned ("ostatnia" = freshest plan per hour). */
684	  private _effectivePinDate(): Date | null {
685	    const iso = this._forecastRunAt ?? this._series?.forecast_pin?.run_at ?? null;
686	    if (!iso) return null;
