691	  /** Step the prognoza pin ±1 h (the ‹ / › buttons). Starts from the effective
692	   *  pin (explicit or preset-resolved), or from the current hour when nothing
693	   *  is pinned yet. Clamped to the current hour — there are no future plans. */
694	  private _shiftForecastPin(deltaHours: number): void {
695	    const base = this._effectivePinDate() ?? new Date();
696	    base.setMinutes(0, 0, 0);
697	    base.setHours(base.getHours() + deltaHours);
698	    const nowHour = new Date();
699	    nowHour.setMinutes(0, 0, 0);
700	    if (base.getTime() > nowHour.getTime()) base.setTime(nowHour.getTime());
701	    this._forecastRunAt = base.toISOString();
702	    this._ensurePinVisible(base);
703	    this._refresh();
704	  }
