706	  /** A pin outside the visible window would change nothing on screen — jump
707	   *  the window (half-day aligned, matching the « / » stepping) so the pinned
708	   *  moment and its coverage band are in view. */
709	  private _ensurePinVisible(pin: Date): void {
710	    const { start, end } = this._computeWindow();
711	    if (pin.getTime() >= start.getTime() && pin.getTime() < end.getTime()) return;
712	    const base = this._midnight(pin);
713	    if (pin.getHours() >= 12) base.setHours(12);
714	    this._anchor =
715	      base.getTime() >= this._midnight(new Date()).getTime() ? null : base;
716	  }
