805	  // Simulations: snapshot list + A/B payloads + accuracy
806	  // ------------------------------------------------------------------
807	  private async _loadSimulations(): Promise<void> {
808	    if (!this.hass) return;
809	    this._simLoading = true;
810	    try {
811	      const list = await this.hass.callWS({ type: "powerpilot/snapshots" });
812	      const runs: SnapshotRun[] = list?.runs ?? [];
813	      this._snapshotRuns = runs;
814	      if (runs.length) {
815	        // A = newest vintage; B = one from ~24 h earlier (else the oldest).
816	        if (!this._snapA || !runs.some((r) => r.run_at === this._snapA)) {
817	          this._snapA = runs[0].run_at;
818	        }
819	        if (!this._snapB || !runs.some((r) => r.run_at === this._snapB)) {
820	          const aTime = new Date(this._snapA!).getTime();
821	          const target = aTime - 24 * 3600 * 1000;
822	          let best = runs[runs.length - 1];
823	          for (const r of runs) {
824	            if (r.run_at === this._snapA) continue;
825	            if (
826	              Math.abs(new Date(r.run_at).getTime() - target) <
827	              Math.abs(new Date(best.run_at).getTime() - target)
828	            )
829	              best = r;
830	          }
831	          this._snapB = best.run_at;
832	        }
833	        await Promise.all([
834	          this._loadSnapshotData("A"),
835	          this._loadSnapshotData("B"),
836	        ]);
837	      }
838	      await this._loadAccuracy();
839	      this._error = null;
840	    } catch (err: any) {
841	      this._error = err?.message ?? String(err);
842	    } finally {
843	      this._simLoading = false;
844	    }
845	  }
