847	  private async _loadSnapshotData(which: "A" | "B"): Promise<void> {
848	    if (!this.hass) return;
849	    const runAt = which === "A" ? this._snapA : this._snapB;
850	    if (!runAt) return;
851	    const data: SnapshotPayload = await this.hass.callWS({
852	      type: "powerpilot/snapshot",
853	      run_at: runAt,
854	    });
855	    if (which === "A") this._snapDataA = data;
856	    else this._snapDataB = data;
857	  }
