1148	  protected updated(_changed: Map<string, unknown>): void {
1149	    // Tear down each tab's charts when it isn't active, to free resources.
1150	    if (this._tab !== "overview" && (this._energyChart || this._priceChart)) {
1151	      this._energyChart?.destroy();
1152	      this._priceChart?.destroy();
1153	      this._energyChart = undefined;
1154	      this._priceChart = undefined;
1155	      this._lastMountedSeries = undefined;
1156	    }
1157	    if (this._tab !== "simulations") this._destroySimCharts();
1158	
1159	    // _mountOrUpdateCharts short-circuits when the Series reference hasn't
1160	    // changed, so unrelated state updates (legend hover, log polling) don't
1161	    // trash zoom state.
1162	    if (this._tab === "overview") this._mountOrUpdateCharts();
1163	    else if (this._tab === "simulations") this._mountSimCharts();
1164	  }
