1943	  private _evAwayAnnotations(): any[] {
1944	    const regions: any[] = [];
1945	    for (const t of this._chartTrips()) {
1946	      const depart = new Date(t.depart).getTime();
1947	      const ret = new Date(t.return_end).getTime();
1948	      if (isNaN(depart) || isNaN(ret) || ret <= depart) continue;
1949	      // Clamp event bounds into the away window; fall back to one event-colored
1950	      // band when the calendar times are missing/degenerate.
1951	      let evStart = new Date(t.event_start).getTime();
1952	      let evEnd = new Date(t.event_end).getTime();
1953	      if (isNaN(evStart) || isNaN(evEnd) || evEnd <= evStart) {
1954	        evStart = depart;
1955	        evEnd = ret;
1956	      }
1957	      evStart = Math.max(depart, Math.min(evStart, ret));
1958	      evEnd = Math.max(evStart, Math.min(evEnd, ret));
1959	
1960	      // Truncated horizontal label on the event band only; the tooltip shows
1961	      // the full event name + details for every hour inside the window.
1962	      const label = {
1963	        text: `🚗 ${t.label.length > 22 ? t.label.slice(0, 21) + "…" : t.label}`,
1964	        orientation: "horizontal",
1965	        position: "top",
1966	        offsetY: -6,
1967	        style: { background: TRIP_FILL.event, color: "#ffffff", fontSize: "10px" },
1968	      };
1969	      if (evStart > depart)
1970	        regions.push({ x: depart, x2: evStart, fillColor: TRIP_FILL.travel, opacity: 0.16 });
1971	      regions.push({ x: evStart, x2: evEnd, fillColor: TRIP_FILL.event, opacity: 0.16, label });
1972	      if (ret > evEnd)
1973	        regions.push({ x: evEnd, x2: ret, fillColor: TRIP_FILL.travel, opacity: 0.16 });
1974	    }
1975	    return regions;
