1978	  /** Manual ("forced") calendar windows as shaded x-axis regions. */
1979	  private _evForcedAnnotations(): any[] {
1980	    const HOUR = 3600 * 1000;
1981	    const hours = (this._status?.ev?.forced_hours ?? [])
1982	      .map((iso) => new Date(iso).getTime())
1983	      .filter((t) => !isNaN(t))
1984	      .sort((a, b) => a - b);
1985	    if (!hours.length) return [];
1986	    // Merge consecutive 1-hour slots into one region.
1987	    const regions: { x: number; x2: number }[] = [];
1988	    let start = hours[0];
