1992	      if (cur !== prev + HOUR) {
1993	        regions.push({ x: start, x2: prev + HOUR });
1994	        if (cur != null) start = cur;
1995	      }
1996	      prev = cur;
1997	    }
1998	    return regions.map((r) => ({
1999	      x: r.x,
2000	      x2: r.x2,
2001	      fillColor: "#3498db",
2002	      opacity: 0.1,
2003	      label: {
