2199	  /** Simple index-based polyline used by the forecast overlay. */
2200	  private _linePath(values: number[], min: number, max: number, w: number, h: number): string {
2201	    const n = values.length;
2202	    if (n < 2) return "";
2203	    const span = max - min || 1;
2204	    const pad = 6;
2205	    const innerH = h - pad * 2;
2206	    let d = "";
2207	    let started = false;
2208	    values.forEach((v, i) => {
2209	      if (isNaN(v)) {
2210	        started = false;
2211	        return;
2212	      }
2213	      const x = (i / (n - 1)) * w;
2214	      const yy = pad + innerH - ((v - min) / span) * innerH;
2215	      d += `${started ? "L" : "M"}${x.toFixed(1)},${yy.toFixed(1)} `;
2216	      started = true;
2217	    });
2218	    return d.trim();
2219	  }
