2582	  /** Merge consecutive 1-hour forced slots into "HH:MM–HH:MM" ranges. */
2583	  private _evForcedRanges(hours: string[]): string[] {
2584	    const sorted = [...hours]
2585	      .map((iso) => new Date(iso))
2586	      .filter((d) => !isNaN(d.getTime()))
2587	      .sort((a, b) => a.getTime() - b.getTime());
2588	    if (!sorted.length) return [];
2589	    const fmt = (d: Date) =>
2590	      d.toLocaleTimeString("pl-PL", { hour: "2-digit", minute: "2-digit" });
2591	    const fmtDay = (d: Date) =>
2592	      d.toLocaleDateString("pl-PL", { day: "2-digit", month: "2-digit" });
2593	    const ranges: string[] = [];
2594	    let start = sorted[0];
2595	    let prev = sorted[0];
2596	    for (let i = 1; i <= sorted.length; i++) {
2597	      const cur = sorted[i];
2598	      const contiguous =
2599	        cur && cur.getTime() - prev.getTime() === 3600_000;
2600	      if (!contiguous) {
2601	        const end = new Date(prev.getTime() + 3600_000);
2602	        ranges.push(`${fmtDay(start)} ${fmt(start)}–${fmt(end)}`);
2603	        if (cur) start = cur;
2604	      }
2605	      prev = cur;
2606	    }
2607	    return ranges;
2608	  }
