3083	  /** SVG daily bar chart for the last 30 days of a profile, with a kWh axis. */
3084	  private _dailyBars(p: StatProfile): TemplateResult {
3085	    const days = p.daily.slice(-30);
3086	    if (!days.length) return html`<div class="empty">Brak danych dziennych.</div>`;
3087	    const max = Math.max(0.001, ...days.map((d) => d.kwh));
3088	    const w = 760;
3089	    const ht = 220;
3090	    const padB = 26; // x labels
3091	    const padT = 10;
3092	    const padL = 42; // y labels
3093	    const gap = 3;
3094	    const plotW = w - padL;
3095	    const plotH = ht - padB - padT;
3096	    const bw = (plotW - (days.length - 1) * gap) / days.length;
3097	    const dark = this._isDark();
3098	    const fg = dark ? "#9ca3af" : "#6b7280";
3099	    const grid = dark ? "rgba(255,255,255,0.10)" : "rgba(0,0,0,0.08)";
3100	    const yFor = (v: number) => padT + plotH - (v / max) * plotH;
3101	    // "Nice" gridline step so labels read cleanly (e.g. 0 / 5 / 10 / 15 kWh).
3102	    const rawStep = max / 4;
3103	    const mag = Math.pow(10, Math.floor(Math.log10(rawStep)));
3104	    const niceStep = [1, 2, 2.5, 5, 10].find((m) => m * mag >= rawStep)! * mag;
3105	    const ticks: number[] = [];
3106	    for (let v = 0; v <= max + 1e-9; v += niceStep) ticks.push(v);
3107	
3108	    return html`
3109	      <svg viewBox="0 0 ${w} ${ht}" class="chart" style="width:100%">
3110	        ${ticks.map(
3111	          (v) => svg`
3112	            <line x1=${padL} y1=${yFor(v)} x2=${w} y2=${yFor(v)} stroke=${grid} stroke-width="1"></line>
3113	            <text x=${padL - 6} y=${yFor(v) + 3} text-anchor="end" font-size="10" fill=${fg}>${v.toFixed(v < 10 ? 1 : 0)}</text>`
3114	        )}
3115	        <text x="2" y=${padT + 4} font-size="10" fill=${fg}>kWh</text>
3116	        ${days.map((d, i) => {
3117	          const h = (d.kwh / max) * plotH;
3118	          const x = padL + i * (bw + gap);
3119	          const y = padT + plotH - h;
3120	          const dt = new Date(d.date + "T00:00:00");
3121	          const weekend = dt.getDay() === 0 || dt.getDay() === 6;
3122	          const color = d.partial ? "#9ca3af" : weekend ? "#f59e0b" : "#3b82f6";
3123	          const ds = dt.toLocaleDateString("pl-PL", { day: "2-digit", month: "2-digit" });
3124	          const label = `${ds}: ${d.kwh.toFixed(2)} kWh${d.partial ? " (dziś, niepełny)" : ""}`;
3125	          return svg`<rect x=${x} y=${y} width=${Math.max(bw, 0.5)} height=${Math.max(h, 0)}
3126	              rx="1.5" fill=${color} opacity=${d.partial ? 0.5 : 0.9}>
3127	              <title>${label}</title></rect>
3128	            ${
3129	              i % 5 === 0
3130	                ? svg`<text x=${x + bw / 2} y=${ht - 8} text-anchor="middle" font-size="10" fill=${fg}>${ds}</text>`
3131	                : nothing
3132	            }`;
3133	        })}
3134	      </svg>
3135	      <div class="legend-row">
3136	        <span><i class="dot-sq" style="background:#3b82f6"></i> dzień roboczy</span>
3137	        <span><i class="dot-sq" style="background:#f59e0b"></i> weekend</span>
3138	        <span><i class="dot-sq" style="background:#9ca3af"></i> dziś (niepełny)</span>
3139	        <span class="muted">najedź na słupek, by zobaczyć dokładną wartość</span>
3140	      </div>
3141	    `;
3142	  }
