3384	  private _eventDetails(e: LogEvent): string {
3385	    const bits: string[] = [];
3386	    if (e.errors && e.errors.length) bits.push("⚠ " + e.errors.join("; "));
3387	    if (e.extra) {
3388	      for (const [k, v] of Object.entries(e.extra)) {
3389	        if (v == null) continue;
3390	        const s = Array.isArray(v)
3391	          ? `[${v.length}]`
3392	          : typeof v === "object"
3393	          ? JSON.stringify(v)
3394	          : String(v);
3395	        bits.push(`${k}=${s}`);
3396	      }
3397	    }
3398	    return bits.join(" · ") || "—";
3399	  }
