def charger_power_kw(self) -> float:
    """Total charger draw (kW) at full power across all phases."""
    phases = max(int(self.config.get(CONF_EV_CHARGER_PHASES, 1) or 1), 1)
    if self.config.get(CONF_EV_CURRENT_CONTROL):
